package tn.esprit.partnerintelligence.observability;import io.micrometer.core.instrument.MeterRegistry;import org.springframework.stereotype.Component;@Component public class MetricsPublisher{ private final MeterRegistry r; public MetricsPublisher(MeterRegistry r){this.r=r;} public void inference(String type){ r.counter("partner_intelligence_inference_total","type",type).increment(); }}